-- --------------------------------------------------------------------------
-- Request For Quotation (bus_request_for_quotation)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('55852c85-5374-5c19-b2e5-520558b4fa0b', 'Request For Quotation', 'Maintain Request For Quotation records', 'Create, find and maintain Request For Quotation records. The list shows every Request For Quotation you have access to — select a row to open it, or use New to add one. Each row is a single Request For Quotation, described by 5 fields.

Id and Rfq Number are unique: no two Request For Quotation records may share the same value, and a save that would duplicate one is rejected. Rfq Number and Status must be filled in before the record can be saved.

Request For Quotation Line, Supplier Quotation and Purchase Order refer back to Request For Quotation, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Request For Quotation then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Request For Quotation with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('00fd1e26-4607-5125-ba81-aedecd097c87', 'bus_request_for_quotation', 'Request For Quotation', 'Governs solicitation of supplier offers for approved procurement demand. PurchaseRequisition authorizes internal demand; RequestForQuotation solicits offers; SupplierQuotation records offers; PurchaseOrder creates the external commitment. Strategic sourcing, competitive procurement, supplier selection, negotiation, compliance, and audit. Bridges requisitions and suppliers to comparable responses and resulting purchase orders. Draft → issued → closed/awarded, with cancellation. Demand or supplier eligibility changes revalidate open sourcing; awarded history remains auditable and downstream orders require controlled amendment.', 'A', FALSE, FALSE, FALSE, TRUE, '55852c85-5374-5c19-b2e5-520558b4fa0b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
