-- --------------------------------------------------------------------------
-- Supplier Quotation (bus_supplier_quotation)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2db39ffb-7df8-5d15-a8a9-f6427ab853c7', 'Supplier Quotation', 'Maintain Supplier Quotation records', 'Create, find and maintain Supplier Quotation records. The list shows every Supplier Quotation you have access to — select a row to open it, or use New to add one. Each row is a single Supplier Quotation, described by 8 fields.

Id is unique: no two Supplier Quotation records may share the same value, and a save that would duplicate one is rejected. Quotation Number, Submitted At, Status, Supplier and Request For Quotation must be filled in before the record can be saved.

Every Supplier Quotation points at Supplier and Request For Quotation. Choose the linked record from the lookup on those fields rather than typing an identifier. Supplier Quotation Line and Purchase Order refer back to Supplier Quotation, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Supplier Quotation then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Supplier Quotation with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('32c875c3-8ff0-5a7a-b1b6-6ab698cfc3b0', 'bus_supplier_quotation', 'Supplier Quotation', 'Preserves a supplier''s commercial response to governed sourcing. SupplierQuotation is evidence of an offer; RequestForQuotation is the solicitation; PurchaseOrder is the later commitment. Sourcing, bid comparison, negotiation, supplier selection, procurement compliance, and audit. Connects Supplier and RFQ to resulting PurchaseOrders without conflating offer and commitment. Received → under review → accepted/rejected/expired/withdrawn. Supplier qualification, RFQ changes, and validity changes revalidate open evaluation; accepted historical offers remain immutable evidence.', 'A', FALSE, FALSE, FALSE, TRUE, '2db39ffb-7df8-5d15-a8a9-f6427ab853c7', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4be947f-ce8f-58e0-b4d8-2497eed497b0', '2db39ffb-7df8-5d15-a8a9-f6427ab853c7', '32c875c3-8ff0-5a7a-b1b6-6ab698cfc3b0', 'Supplier Quotation', 'Shows one Supplier Quotation at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Supplier and Request For Quotation are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
