VALUES ('7435da94-b2db-5314-a07d-5042776384ae', '709d6477-9454-5630-a15d-1bb1fde247fa', 'notes', 'Notes', 'Receiving notes and operational context. Human-readable context for receipt exceptions or inspection. Operations and audit. Does not replace structured disposition or return evidence. Supports review. Optional.', 10, 2000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
