INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('73f45171-6723-5a10-8bef-a9cb8c997cbf', '577e438a-ee71-5a07-8238-2fc65b87a83d', '03af7b1b-89b8-5f91-b6c5-2ca0e3db296b', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Resolution Code', 'Agreed outcome category of the supplier claim. Records the high-level outcome without itself executing the resulting transaction. Supports supplier performance recovery analytics and downstream workflow routing. Detailed authorization is represented by SupplierClaimResolution; RETURN may create SupplierReturn; CREDIT may create SupplierCreditNote; DEBIT_ADJUSTMENT may create SupplierDebitNote. Summarizes the resolution after agreement. Optional until resolution is agreed.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
