-- --------------------------------------------------------------------------
-- Supplier Credit Note Application (bus_supplier_credit_note_application)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f4fecbd4-dd20-5050-9d6c-5158958ff885', 'Supplier Credit Note Application', 'Maintain Supplier Credit Note Application records', 'Create, find and maintain Supplier Credit Note Application records. The list shows every Supplier Credit Note Application you have access to — select a row to open it, or use New to add one. Each row is a single Supplier Credit Note Application, described by 9 fields.

Id is unique: no two Supplier Credit Note Application records may share the same value, and a save that would duplicate one is rejected. Supplier Credit Amount, Invoice Amount, Applied At, Status, Supplier Credit Note and Invoice must be filled in before the record can be saved.

Every Supplier Credit Note Application points at Exchange Rate, Supplier Credit Note and Invoice. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Supplier Credit Note Application then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Supplier Credit Note Application with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'bus_supplier_credit_note_application', 'Supplier Credit Note Application', 'Provides the auditable bridge by which a posted SupplierCreditNote is consumed against a purchase Invoice. SupplierCreditNote establishes the authorized payable reduction; Invoice remains the original claim; SupplierCreditNoteApplication records exactly where and how much of the credit was used. Accounts payable, supplier returns, supplier statements, invoice reconciliation, tax, audit and payment planning. SupplierCreditNoteLine explains source credit detail; InvoiceLine explains original payable detail; this entity records header-level application evidence; JournalEntry records accounting recognition. SupplierCreditNote posted → select eligible purchase Invoice → validate remaining credit and payable exposure → currency/rate validation → activate application → update SupplierCreditNote amountApplied/amountUnapplied and payable exposure → reverse and reallocate when required. Draft → active → reversed/cancelled. Historical applications are retained. Changes to posted SupplierCreditNote or Invoice never rewrite an application; corrections use reversal and replacement applications. A posted USD 1,000 SupplierCreditNote is applied to a USD 1,000 purchase invoice. The application consumes USD 1,000 of available supplier credit and reduces the payable exposure by USD 1,000. If applied incorrectly, the application is reversed and a new application is created.', 'A', FALSE, FALSE, FALSE, TRUE, 'f4fecbd4-dd20-5050-9d6c-5158958ff885', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ed3c228b-e952-5907-9a08-da6038c4676c', 'f4fecbd4-dd20-5050-9d6c-5158958ff885', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'Supplier Credit Note Application', 'Shows one Supplier Credit Note Application at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Exchange Rate, Supplier Credit Note and Invoice are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4eff678d-b781-54e1-accb-2291bca54b1b', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'id', 'Id', 'Immutable identity of the supplier credit application. Identifies one controlled application independently of its supplier credit and invoice. Used for payable reconciliation, audit, reversal and settlement projections. SupplierCreditNote supplies the adjustment; Invoice supplies the payable claim; this entity records the application bridge. Stable reference for applying and reversing supplier credit. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bbd3e426-e440-577f-8ebc-db09a8e7fcfe', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'supplier_credit_amount', 'Supplier Credit Amount', 'Portion of the SupplierCreditNote consumed by this application. Represents the source-side amount of supplier credit allocated to an invoice. Controls remaining unapplied supplier credit and reconciliation. Must use the SupplierCreditNote currency. Establishes the amount consumed from the supplier credit. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('81cb426a-2685-5542-af7f-4e6e45ca6d6a', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'invoice_amount', 'Invoice Amount', 'Amount by which the purchase Invoice payable claim is reduced. Represents the target-side financial effect on the payable. Drives payable exposure and reconciliation. Must use the Invoice currency and may differ from supplierCreditAmount only under governed exchange-rate treatment. Supplies the claim-side adjustment. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c825bb9f-7a02-52da-8576-06ee25478772', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'exchange_rate_id', 'Exchange Rate', 'Exchange rate used when supplier credit and invoice currencies differ. Preserves conversion evidence for cross-currency supplier credit application. Supports audit and reproducibility. Required for permitted cross-currency applications. Connects source supplier credit value to target invoice value. Optional when currencies are identical.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bd7e4aeb-733f-5402-8d75-4c4c1098d036', '8031adea-5a3c-5c3f-92c9-71cade0fc2ec', 'applied_at', 'Applied At', 'Timestamp when the supplier credit application became effective. Establishes adjustment chronology. Supports accounting periods, supplier statements, audit and reconciliation. Distinct from SupplierCreditNoteDate and InvoiceDate. Determines when payable exposure changes. Required.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
