-- --------------------------------------------------------------------------
-- Purchase Requisition Line (bus_purchase_requisition_line)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'bus_purchase_requisition_line', 'Purchase Requisition Line', 'Represents one measurable internal procurement demand before it becomes an external supplier commitment. PurchaseRequisitionLine is where a business need becomes specific enough for procurement to source, approve, compare, and eventually order. It is demand, not yet a purchase obligation. Used by requesters, approvers, buyers, sourcing teams, inventory planners, and procurement workflows. PurchaseRequisition provides internal authorization context. Product and UnitOfMeasure provide meaning to the requested quantity. If approved and sourced, this demand may be transformed into one or more PurchaseOrderLines; the resulting order line is a separate commercial commitment and must retain traceability to the originating demand. A line begins as requested demand, participates in requisition review and approval, may be sourced or rejected, and may result in a purchase-order commitment. A requisition line can be partially ordered when demand is fulfilled through multiple suppliers, deliveries, or purchase orders. A depot technician requests 20 replacement door seals needed by a specified date. The line references the standardized seal Product and its unit, while the description records the equipment/application requirement. Procurement may source the demand from an approved Supplier and create a PurchaseOrderLine for the quantity actually committed.', 'A', FALSE, FALSE, FALSE, TRUE, '66a16fa1-bbde-5b3d-8205-c4387db4feaf', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8e6ec59d-2cb6-5443-8535-aa8bb08835d2', '66a16fa1-bbde-5b3d-8205-c4387db4feaf', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'Purchase Requisition Line', 'Shows one Purchase Requisition Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Product and Unit Of Measure are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6fb1eea0-14b6-54f3-83e3-d1d908eec25d', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'id', 'Id', 'The immutable system identity of the requisition line. Used to trace the exact internal demand through approval, sourcing, purchase-order creation, fulfillment, and reporting. Identifies this demand line independently of the parent requisition, Product, or any later PurchaseOrderLine created from it. Required because each procurement demand must remain individually traceable.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fef62faf-ee4d-5c5a-a39d-425098cda0be', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'line_number', 'Line Number', 'The business sequence number identifying the demand line within its PurchaseRequisition. Used by requesters, approvers, buyers, documents, and integrations to refer to a specific requested item or service. Meaningful only within the containing requisition; it is not a global identifier. Required for human-readable requisition processing.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('99fcf47c-cdbd-59ce-a4cf-6eb999e133d2', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'quantity', 'Quantity', 'The quantity of goods, materials, assets, or service units requested by the requester. Used for approval, sourcing, supplier quotation, planning, and eventual conversion into a purchase commitment. Quantity requires Product and UnitOfMeasure context to be meaningful and may differ from the quantity eventually ordered. Required because procurement demand must state the requested magnitude.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('871da4be-aaac-5087-b1a1-ea5e96b757ed', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'requested_date', 'Requested Date', 'The date by which the requester needs the requested goods or service to be available or completed. Used for prioritization, sourcing, purchasing lead-time analysis, supplier selection, and delivery planning. This is an internal need date and is distinct from the PurchaseOrder requestedDeliveryDate, Supplier promise date, and actual receipt date. Optional when the requester has no fixed need-by date.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('09d06a89-58c3-52a8-8616-ecac0c2e59e2', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'description', 'Description', 'The human-readable description of the requested item or service, including requirements that may not be represented by the Product reference alone. Used by approvers and buyers to understand the demand, obtain quotations, clarify specifications, and communicate requirements to suppliers. Description supplements Product; it must not silently replace a known Product identity when standardized master data exists. Required because procurement demand must remain understandable even when product master data is incomplete.', 10, 1000, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4841407a-0093-513e-a4ba-3da0ec0ce216', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'requisition_id', 'Requisition', 'Identifies the PurchaseRequisition that owns this internal procurement demand. Supplies requester, organization, approval, supplier preference, and requisition lifecycle context. Every requisition line belongs to exactly one PurchaseRequisition. The parent requisition controls the internal authorization context; the line provides the measurable demand.', 19, NULL, NULL, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('87ddf450-aa72-506c-b410-d665ced554b9', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'product_id', 'Product', 'Identifies the standardized Product being requested when the demand can be expressed using product master data. Enables sourcing, catalog selection, inventory checks, specification validation, and conversion to a PurchaseOrderLine. Zero or one Product may be referenced because some requisitions begin as free-text or service requirements. A missing Product does not invalidate the demand; it indicates that purchasing may need to identify or create the appropriate product definition.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e8e4d00d-ff57-5da6-a2e7-77492f434941', '4f9f7d2d-8a90-5bd6-a749-b3d4ea157422', 'unit_of_measure_id', 'Unit Of Measure', 'Defines the unit in which the requested quantity is expressed. Used to interpret quantities during approval, sourcing, quotation comparison, ordering, receipt, and conversion. Zero or one unit may be specified; the product''s default unit may be inherited where applicable. UnitOfMeasure gives semantic meaning to quantity and supports conversion when the ordered unit differs from the requested unit.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
