INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b3a8ca79-9b24-54f3-bc46-b103484a758c', 'bus_request_for_quotation_line', 'Request For Quotation Line', 'Line-level bridge from approved procurement demand to comparable supplier offers. The RFQ header controls the sourcing event; this line defines exactly what is being sourced. Strategic sourcing, competitive bids, services procurement, award allocation, and audit. PurchaseRequisitionLine supplies demand; SupplierQuotationLine supplies responses; PurchaseOrderLine executes awarded commitment. Prepared with RFQ, issued for response, closed/awarded with sourcing event, retained historically. Issued-line changes revalidate supplier responses and downstream awards without rewriting historical submissions.', 'A', FALSE, FALSE, FALSE, TRUE, '55852c85-5374-5c19-b2e5-520558b4fa0b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c61b4d5d-3687-5cdc-a588-62a648d1d587', '55852c85-5374-5c19-b2e5-520558b4fa0b', 'b3a8ca79-9b24-54f3-bc46-b103484a758c', 'Request For Quotation Line', 'Shows one Request For Quotation Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Request For Quotation, Product and Unit Of Measure are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
