INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1cddffa3-2d43-5b0a-b690-d9a774035a4e', 'bus_supplier_quotation_line', 'Supplier Quotation Line', 'Line-level supplier offer used for sourcing comparison and controlled conversion to purchase commitment. SupplierQuotationLine is commercial evidence, while PurchaseOrderLine is the binding procurement commitment. Bid comparison, negotiation, split award, purchase-order generation, compliance, and audit. Answers RequestForQuotationLine and may produce one or more PurchaseOrderLines. Received → evaluated → accepted/partially accepted/rejected → retained as sourcing evidence. Offer or award changes revalidate downstream unissued commitments; issued commitments require controlled amendments.', 'A', FALSE, FALSE, FALSE, TRUE, '2db39ffb-7df8-5d15-a8a9-f6427ab853c7', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ee79548-7b93-5053-8860-b70bb83cc5f1', '2db39ffb-7df8-5d15-a8a9-f6427ab853c7', '1cddffa3-2d43-5b0a-b690-d9a774035a4e', 'Supplier Quotation Line', 'Shows one Supplier Quotation Line at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Request For Quotation Line, Supplier Quotation, Product and Unit Of Measure are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
