INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7f4fd96f-5625-5ba6-a7ef-f816348e42a9', 'ffd13183-b176-5b4d-a1c4-12b86ed68320', 'accepted_quantity', 'Accepted Quantity', 'Quantity accepted after receiving controls. Represents quantity eligible for normal inventory posting and normally later supplier return. Inventory, PO fulfillment, matching and supplier returns. SupplierReturnLine quantity cannot normally exceed accepted quantity remaining after prior returns. Provides authoritative eligibility basis. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
