INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('28688886-0d1f-5ef7-84ec-0f51fe42d9c5', 'ffd13183-b176-5b4d-a1c4-12b86ed68320', 'rejected_quantity', 'Rejected Quantity', 'Quantity rejected at receipt. Records quantity not accepted into normal inventory. Quality and supplier dispute processing. Rejected quantity is not normally eligible for a supplier return because it was not accepted inventory; explicit exception workflows may differ. Provides disposition evidence. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a404c32c-21fe-5b12-8b48-b950a7258609', 'ffd13183-b176-5b4d-a1c4-12b86ed68320', 'pending_inspection_quantity', 'Pending Inspection Quantity', 'Quantity awaiting inspection or disposition. Records unresolved receipt quantity. Quality, receiving and inventory controls. Pending quantity cannot normally be returned as accepted stock until controlled disposition establishes eligibility. Blocks premature supplier-return eligibility. Required.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
