INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('35ce6f78-0d06-516a-8a29-0220734ece74', 'ffd13183-b176-5b4d-a1c4-12b86ed68320', 'unit_price', 'Unit Price', 'Procurement price basis applicable at receipt time. Supports receipt valuation, accruals and invoice matching. Normally inherited from PurchaseOrderLine but may reflect authorized receipt-specific adjustment. Provides financial context without replacing PO commitment.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
