INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('36736a27-70d1-5902-9041-540af7d4979e', '2b34b6e8-3622-576f-a6a7-c6612e4115c1', '35ce6f78-0d06-516a-8a29-0220734ece74', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Unit Price', 'Procurement price basis applicable at receipt time. Supports receipt valuation, accruals and invoice matching. Normally inherited from PurchaseOrderLine but may reflect authorized receipt-specific adjustment. Provides financial context without replacing PO commitment.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
