VALUES ('30a75478-e490-535e-9b1a-aae96e0bee98', '2b34b6e8-3622-576f-a6a7-c6612e4115c1', '0021529c-1728-58a1-9b91-3d175f984e1b', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Notes', 'Receiving notes and line-specific context. Explains exceptions or inspection findings. Operations and audit. Does not replace structured disposition or return evidence. Supports review. Optional. Up to 2000 characters.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
