INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('226a5de2-c1ad-5b2a-860a-99c9671ac729', '704ce9b7-0396-5925-af00-830915fb6a18', 'supplier_claim_id', 'Supplier Claim', 'Claim evidence supporting the debit line. Connects the monetary adjustment to the supplier issue being recovered. Investigation approval and audit. Supplies justification for the debit.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
