INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('64a1def3-c6ce-536e-b2ef-9a07bfa70ff3', '704ce9b7-0396-5925-af00-830915fb6a18', 'supplier_claim_resolution_id', 'Supplier Claim Resolution', 'Authorized claim resolution supporting this debit line. Links the line to the approved recovery decision and its financial limit. Approval audit and claim closure. Supplies remedy authorization for DEBIT_ADJUSTMENT.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
