INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2a5cd4b6-3ca5-5d69-8493-66735d8d7945', '36cc0896-81f2-5010-a098-89ed26a571ec', '8a20d4b5-f5c1-571f-860c-34c45b5b94f9', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Supplier Return', 'Parent reverse-procurement transaction containing this line. Supplies supplier, authorization and overall lifecycle context. Controls whether this line may execute. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
