VALUES ('db4b6ddf-6e5c-5476-b183-604c207c92ce', 'd25babe6-1284-5194-aedd-935b223d4afc', '35e041e2-9a89-5ca7-8e33-0ab032d74c3a', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Product', 'Product or service identified by the original invoice line. Identifies what was billed without making current product master data a live dependency of posted history. Supports billing, fulfillment and return traceability. Supplies source item context.', 190, 190, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
