VALUES ('7db5282e-0016-5ea5-8ef7-5373553aa7c1', 'd25babe6-1284-5194-aedd-935b223d4afc', '4bb032d6-4aee-5471-9e57-114d30988946', '8b7abcb0-9528-5a22-8230-ba58e969a2ee', 'Invoice', 'Parent invoice containing the original claim line. Provides financial document context. Supports billing, settlement, adjustment and audit. Parent claim owns the line''s historical calculation. Required — the record cannot be saved while this is empty.', 200, 200, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
